const ChatTypingUI: React.FC<ChatTypingUIProps> = ({
  backgroundColor = "#171717",
  transparentBackground = false,
  durationInSeconds = 14,
  textToType = "Create a promo for a photo of a woman with sunglasses",
  typingSpeed = 1,
  accentColor = "#8E59FF",
  responseToType = "Here's a clean, high-quality prompt you can use:\n\nPrompt:\nA realistic photo of a stylish woman wearing modern sunglasses. She stands outdoors with natural lighting, a soft background blur, and subtle highlights on the glasses. Her expression is confident, her hair moves gently with the wind, and the overall mood is elegant and contemporary. High detail in skin",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Timings ---
  const entranceStart = 10;
  const colorTransitionStart = 35;
  const colorTransitionEnd = 55;
  const startTypingFrame = 60;
  
  // Speed up user typing duration to allow timeline split
  const userTypingLength = textToType.length;
  const userTypingDuration = Math.ceil(userTypingLength / typingSpeed); 
  const endTypingFrame = startTypingFrame + userTypingDuration;

  // Transition Phase 1: Prompt Bubble Fly-up (Input Box stays centered)
  const promptFlyUpStartFrame = endTypingFrame + 15;
  const promptFlyUpEndFrame = promptFlyUpStartFrame + 25;

  // Transition Phase 2: Input Box Moves Down
  const boxMoveDownStartFrame = promptFlyUpEndFrame + 10;
  const boxMoveDownEndFrame = boxMoveDownStartFrame + 25;

  // Response Phase
  const startResponseFrame = boxMoveDownEndFrame + 15;
  const totalFrames = durationInSeconds * fps;
  const endResponseFrame = Math.min(totalFrames - 15, startResponseFrame + 180);

  // --- Layout Entrance Animations ---
  const sidebarOpacity = interpolate(frame, [0, entranceStart], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const boxOpacity = interpolate(frame, [entranceStart, entranceStart + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const boxScale = spring({
    frame: frame - entranceStart,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  // --- Button Color Transition ---
  const buttonColor = interpolateColors(
    frame,
    [colorTransitionStart, colorTransitionEnd],
    ["#404040", accentColor]
  );

  const glowScale = interpolate(
    frame,
    [colorTransitionStart, colorTransitionEnd],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const currentShadow = glowScale > 0 ? `0 0 ${40 * s * glowScale}px ${accentColor}80` : "none";

  // --- User Typing Effect Logic ---
  const typingProgress = interpolate(
    frame,
    [startTypingFrame, endTypingFrame],
    [0, textToType.length],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const visibleText = textToType.slice(0, Math.floor(typingProgress));
  const isTyping = frame >= startTypingFrame && frame < endTypingFrame;
  
  const cursorOpacity = isTyping 
    ? 1 
    : (Math.floor(frame / 20) % 2 === 0 ? 1 : 0);

  // --- UI Movement Transitions ---
  const boxY = interpolate(frame, [boxMoveDownStartFrame, boxMoveDownEndFrame], [0, 360 * s], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const inputBoxTextOpacity = interpolate(frame, [promptFlyUpStartFrame, promptFlyUpStartFrame + 5], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- Prompt Bubble Animations ---
  const bubbleOpacity = interpolate(frame, [promptFlyUpStartFrame, promptFlyUpStartFrame + 5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const bubbleX = interpolate(frame, [promptFlyUpStartFrame, promptFlyUpEndFrame], [0, 150 * s], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const bubbleY = interpolate(frame, [promptFlyUpStartFrame, promptFlyUpEndFrame], [0, -320 * s], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- AI Response Typing Logic ---
  const responseOpacity = interpolate(frame, [startResponseFrame, startResponseFrame + 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const responseProgress = interpolate(
    frame,
    [startResponseFrame, endResponseFrame],
    [0, responseToType.length],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const visibleResponseText = responseToType.slice(0, Math.floor(responseProgress));

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, flexDirection: "row", transition: "none" }}>
      
      {/* Sidebar */}
      <div
        style={{
          width: 100 * s,
          height: "100%",
          borderRight: `${2 * s}px solid rgba(255, 255, 255, 0.04)`,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          paddingTop: 50 * s,
          gap: 40 * s,
          opacity: sidebarOpacity,
          zIndex: 10,
          transition: "none",
        }}
      >
        <Img
          src="https://thesvg.org/icons/openai/dark.svg"
          style={{
            width: 40 * s,
            height: 40 * s,
            filter: "brightness(0) invert(1)",
            objectFit: "contain",
            transition: "none",
          }}
        />
        <EditIcon size={34 * s} color="#888888" />
        <SearchIcon size={34 * s} color="#888888" />
        <AppsIcon size={34 * s} color="#888888" />
      </div>

      {/* Main Content Area */}
      <div
        style={{
          flex: 1,
          position: "relative",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        {/* Header */}
        <div
          style={{
            position: "absolute",
            top: 40 * s,
            left: 40 * s,
            right: 40 * s,
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            opacity: sidebarOpacity,
            transition: "none",
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: 8 * s, transition: "none" }}>
            <span style={{ fontSize: 24 * s, fontWeight: 500, color: "#E3E3E3" }}>ChatGPT 5.1</span>
            <ChevronDownIcon size={18 * s} color="#888888" />
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 24 * s, transition: "none" }}>
            <UserIcon size={24 * s} color="#888888" />
            <MessageIcon size={24 * s} color="#888888" />
          </div>
        </div>

        {/* Prompt Bubble (Flys up from input) */}
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            opacity: bubbleOpacity,
            transform: `translate(calc(-50% + ${bubbleX}px), calc(-50% + ${bubbleY}px))`,
            backgroundColor: accentColor,
            color: "#FFFFFF",
            padding: `${16 * s}px ${32 * s}px`,
            borderRadius: 24 * s,
            fontSize: 28 * s,
            fontWeight: 500,
            maxWidth: 750 * s,
            boxShadow: "0 4px 20px rgba(0, 0, 0, 0.15)",
            whiteSpace: "normal",
            zIndex: 5,
            transition: "none",
          }}
        >
          {textToType}
        </div>

        {/* AI Response Area */}
        <div
          style={{
            position: "absolute",
            left: `calc(50% - 550 * s)`,
            top: `calc(50% - 190 * s)`,
            width: 1100 * s,
            opacity: responseOpacity,
            zIndex: 4,
            transition: "none",
          }}
        >
          <div
            style={{
              fontSize: 26 * s,
              color: "#E3E3E3",
              lineHeight: 1.6,
              fontWeight: 400,
              whiteSpace: "pre-wrap",
              fontFamily: interFamily,
              transition: "none",
            }}
          >
            {visibleResponseText}
            {frame >= startResponseFrame && frame < endResponseFrame && (
              <span
                style={{
                  display: "inline-block",
                  width: 3 * s,
                  height: 26 * s,
                  backgroundColor: accentColor,
                  marginLeft: 4 * s,
                  verticalAlign: "middle",
                  transition: "none",
                }}
              />
            )}
          </div>
        </div>

        {/* Input Box Container */}
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            width: 1100 * s,
            height: 120 * s,
            borderRadius: 60 * s,
            backgroundColor: "rgba(255, 255, 255, 0.04)",
            border: `${2 * s}px solid rgba(255, 255, 255, 0.08)`,
            display: "flex",
            alignItems: "center",
            padding: `0 ${20 * s}px 0 ${30 * s}px`,
            justifyContent: "space-between",
            transform: `translate(-50%, calc(-50% + ${boxY}px)) scale(${boxScale})`,
            opacity: boxOpacity,
            zIndex: 10,
            transition: "none",
          }}
        >
          {/* Left Icons & Text Area */}
          <div style={{ display: "flex", alignItems: "center", gap: 24 * s, flex: 1, overflow: "hidden", transition: "none" }}>
            <PlusIcon size={46 * s} color="#A0A0A0" />
            
            {/* Divider Line */}
            <div style={{ width: 2 * s, height: 44 * s, backgroundColor: "rgba(255, 255, 255, 0.15)", borderRadius: 2 * s, transition: "none" }} />
            
            {/* Text & Cursor Wrapper */}
            <div style={{ flex: 1, display: "flex", alignItems: "center", transition: "none" }}>
              <div
                style={{
                  fontSize: 32 * s,
                  color: "#FFFFFF",
                  whiteSpace: "nowrap",
                  fontWeight: 400,
                  letterSpacing: "-0.5px",
                  opacity: inputBoxTextOpacity,
                  transition: "none",
                }}
              >
                {visibleText}
              </div>
              
              <div
                style={{
                  width: 3 * s,
                  height: 38 * s,
                  backgroundColor: "#FFFFFF",
                  marginLeft: 4 * s,
                  opacity: frame >= promptFlyUpStartFrame ? 0 : cursorOpacity,
                  borderRadius: 2 * s,
                  transition: "none",
                }}
              />
            </div>
          </div>

          {/* Right Icons & Action Button */}
          <div style={{ display: "flex", alignItems: "center", gap: 32 * s, paddingLeft: 24 * s, transition: "none" }}>
            <MicIcon size={40 * s} color="#A0A0A0" />
            
            {/* Submit / Wave Button */}
            <div
              style={{
                width: 80 * s,
                height: 80 * s,
                borderRadius: "50%",
                backgroundColor: buttonColor,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                boxShadow: currentShadow,
                transition: "none",
              }}
            >
              <WaveIcon size={36 * s} color="#FFFFFF" />
            </div>
          </div>
          
        </div>
      </div>
      
    </AbsoluteFill>
  );
};

export default ChatTypingUI;